# guava-swarm-tools/pre-lib.sh: mocks for a GUAVA_PRE script (runs before gnome-shell starts).
#
# Inlined into a bundle with bundle.sh, then pass the bundle as GUAVA_PRE. The bundle must call
# pre_all (or the individual pre_* functions) at its end; see pre-example.sh.
# Inside the harness, $W (/tmp/w) is already set and no session bus exists yet, so this
# library only touches the system bus and PipeWire. Session-bus mocks cannot run here.
#
# Functions:
#   pre_bus        private permissive system bus at $W/sysbus (+ fake-logind when /opt has it)
#   pre_services   python-dbusmock: NetworkManager, BlueZ, UPower, power-profiles-daemon, polkitd
#   pre_mock_state fixtures: a Wi-Fi link with 3 APs, 1 paired+connected BT headset, a 60 % battery
#   pre_audio      PipeWire + WirePlumber + pipewire-pulse with null sinks guava-speakers,
#                  guava-headphones and a virtual mic guava-mic
#   pre_uid_shim   $W/uid.so, an LD_PRELOAD shim whose first getuid() returns 1000 (Nautilus)
#   pre_all        everything above, in order

: "${W:=/tmp/w}"
: "${XDG_RUNTIME_DIR:=$W/run}"
: "${XDG_CONFIG_HOME:=$W/home/.config}"
export W XDG_RUNTIME_DIR XDG_CONFIG_HOME

# _kwait_name BUS NAME [TRIES=40]: wait until NAME has an owner on BUS (system|session).
_kwait_name() {
  local bus=$1 name=$2 i
  for ((i=0; i<${3:-40}; i++)); do
    gdbus call --$bus --dest org.freedesktop.DBus --object-path /org/freedesktop/DBus \
      --method org.freedesktop.DBus.NameHasOwner "$name" 2>/dev/null | grep -q true && return 0
    sleep 0.25
  done
  echo "no owner on $bus bus: $name"
  return 1
}

pre_bus() {
  cat > "$W/sysbus.conf" <<CONF
<!DOCTYPE busconfig PUBLIC "-//freedesktop//DTD D-Bus Bus Configuration 1.0//EN" "http://www.freedesktop.org/standards/dbus/1.0/busconfig.dtd">
<busconfig><type>system</type><listen>unix:path=$W/sysbus</listen><auth>EXTERNAL</auth>
<policy context="default"><allow user="*"/><allow own="*"/><allow send_destination="*"/><allow receive_sender="*"/><allow send_type="method_call"/><allow send_type="signal"/></policy></busconfig>
CONF
  # The root's system bus refuses names whose policy files are not installed, so use this one.
  dbus-daemon --config-file="$W/sysbus.conf" --fork --nopidfile 2>&1
  export DBUS_SYSTEM_BUS_ADDRESS="unix:path=$W/sysbus"
  if [ -f /opt/fake-logind.js ]; then (gjs /opt/fake-logind.js >"$W/fake-logind2.log" 2>&1 &); fi
}

pre_services() {
  local t
  for t in networkmanager bluez5 upower upower_power_profiles_daemon polkitd; do
    python3 -m dbusmock --system --template "$t" >"$W/mock-$t.log" 2>&1 &
  done
  for n in org.freedesktop.NetworkManager org.bluez org.freedesktop.UPower \
           org.freedesktop.UPower.PowerProfiles org.freedesktop.PolicyKit1; do
    _kwait_name system "$n"
  done
}

pre_mock_state() {
  python3 - >"$W/mock-setup.log" 2>&1 <<'PYMOCK'
import dbus
sb = dbus.SystemBus()
def mock(name, path, iface):
    return dbus.Interface(sb.get_object(name, path), iface)
# NetworkManager: a connected Wi-Fi device with three access points
nm = mock("org.freedesktop.NetworkManager", "/org/freedesktop", "org.freedesktop.DBus.Mock")
dev = nm.AddWiFiDevice('mock_wlan0', 'wlan0', dbus.UInt32(100))
ap = nm.AddAccessPoint(dev, 'ap_home', 'Guava Home', '11:22:33:44:55:01', dbus.UInt32(2), dbus.UInt32(5180), dbus.UInt32(540000), dbus.Byte(82), dbus.UInt32(0x100))
nm.AddAccessPoint(dev, 'ap_cafe', 'Cafe Guest', '11:22:33:44:55:02', dbus.UInt32(2), dbus.UInt32(2437), dbus.UInt32(54000), dbus.Byte(48), dbus.UInt32(0))
nm.AddAccessPoint(dev, 'ap_nbr', 'Neighbour 5G', '11:22:33:44:55:03', dbus.UInt32(2), dbus.UInt32(5240), dbus.UInt32(54000), dbus.Byte(25), dbus.UInt32(0x100))
con = nm.AddWiFiConnection(dev, 'con_home', 'Guava Home', 'wpa-psk')
ac = nm.AddActiveConnection([dev], con, ap, 'ac_home', dbus.UInt32(2))
nm.SetGlobalConnectionState(dbus.UInt32(70))
nm.SetConnectivity(dbus.UInt32(4))
try:
    nm.SetProperty('/org/freedesktop/NetworkManager', 'org.freedesktop.NetworkManager', 'PrimaryConnection', dbus.ObjectPath(ac))
    nm.SetProperty('/org/freedesktop/NetworkManager', 'org.freedesktop.NetworkManager', 'PrimaryConnectionType', '802-11-wireless')
except Exception as e:
    print('primary', e)
# BlueZ: one adapter, one paired+connected headset, one paired keyboard, one nearby phone
bz = mock('org.bluez', '/', 'org.bluez.Mock')
bz.AddAdapter('hci0', 'guava-laptop')
for addr, alias, pair, conn in [('AA:BB:CC:00:00:01', 'Studio Headphones', True, True),
                                ('AA:BB:CC:00:00:02', 'Magic Keyboard', True, False),
                                ('AA:BB:CC:00:00:03', 'Phone', False, False)]:
    bz.AddDevice('hci0', addr, alias)
    if pair:
        bz.PairDevice('hci0', addr)
    if conn:
        bz.ConnectDevice('hci0', addr)
# UPower: a laptop battery at 60 %, discharging, 3 h 20 min left, on battery
up = mock('org.freedesktop.UPower', '/org/freedesktop/UPower', 'org.freedesktop.DBus.Mock')
up.AddDischargingBattery('mock_BAT', 'Mock Battery', 60.0, dbus.Int64(12000))
up.SetupDisplayDevice(dbus.UInt32(2), dbus.UInt32(2), 60.0, 30.0, 50.0, 9.0, dbus.Int64(12000), dbus.Int64(0), True, 'battery-good-symbolic', dbus.UInt32(1))
try:
    up.AddProperty('org.freedesktop.UPower', 'OnBattery', True)
except Exception:
    dbus.Interface(sb.get_object('org.freedesktop.UPower', '/org/freedesktop/UPower'), 'org.freedesktop.DBus.Properties').Set('org.freedesktop.UPower', 'OnBattery', True)
# polkit: allow everything (NetworkManager toggles are insensitive otherwise)
dbus.Interface(sb.get_object('org.freedesktop.PolicyKit1', '/org/freedesktop/PolicyKit1/Authority'), 'org.freedesktop.DBus.Mock').AllowUnknown(True)
print('mock state ok')
PYMOCK
  local rc=$?
  cat "$W/mock-setup.log"
  [ $rc = 0 ] || echo "mock setup failed: $(tail -3 "$W/mock-setup.log")"
}

pre_audio() {
  mkdir -p "$XDG_CONFIG_HOME/pipewire/pipewire.conf.d"
  cat > "$XDG_CONFIG_HOME/pipewire/pipewire.conf.d/90-guava-null.conf" <<'CONF'
context.objects = [
  { factory = adapter args = { factory.name = support.null-audio-sink node.name = "guava-speakers" node.description = "Built-in Speakers" media.class = Audio/Sink audio.position = [ FL FR ] monitor.channel-volumes = true } }
  { factory = adapter args = { factory.name = support.null-audio-sink node.name = "guava-headphones" node.description = "USB Headphones" media.class = Audio/Sink audio.position = [ FL FR ] monitor.channel-volumes = true } }
  { factory = adapter args = { factory.name = support.null-audio-sink node.name = "guava-mic" node.description = "Built-in Microphone" media.class = Audio/Source/Virtual audio.position = [ MONO ] } }
]
CONF
  (pipewire >"$W/pw.log" 2>&1 &); sleep 1
  (wireplumber >"$W/wp.log" 2>&1 &); (pipewire-pulse >"$W/pp.log" 2>&1 &); sleep 2
  wpctl status 2>&1 | grep -E "guava|Sinks|Sources" | head -5
}

# uid.c (source, compiled to uid.so):
#   #include <unistd.h>
#   #include <sys/syscall.h>
#   static int n;
#   uid_t getuid(void){ if(n++==0) return 1000; return (uid_t)syscall(SYS_getuid); }
pre_uid_shim() {
  echo '' | base64 -d > "$W/uid.so" && echo "uid shim: $W/uid.so"
}

pre_all() {
  pre_bus
  pre_services
  pre_mock_state
  pre_audio
  pre_uid_shim
}
